<?php
namespace App\Http\Controllers; use App\Services\TilopayProvider; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
class WebhookController extends Controller { public function tilopay(Request $r){$raw=$r->getContent();$event=$r->json('id')??hash('sha256',$raw);if(DB::table('webhook_events')->where('event_id',$event)->exists())return response()->json(['accepted'=>true]);$verified=app(TilopayProvider::class)->verifyWebhook($raw,$r->header('X-Tilopay-Signature'));DB::table('webhook_events')->insert(['provider'=>'tilopay','event_id'=>$event,'status'=>$verified?'verified':'rejected','signature'=>$r->header('X-Tilopay-Signature'),'payload'=>$raw,'correlation_id'=>$r->attributes->get('correlation_id'),'created_at'=>now(),'updated_at'=>now()]);return response()->json(['accepted'=>true],$verified?202:400);} }
